{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "In non-human primates, pharmacologically relevant doses of evobrutinib (the query compound) were detected in CSF after oral administration, directly demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A close analogue with the same acrylamide-piperidine-pyrazolopyridine core achieved a Kp,uu of 0.37 in rat, considered acceptable brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Ibrutinib, a structurally related BTK inhibitor, showed a protein-binding-corrected CSF/plasma ratio of 28.7% in humans, supporting meaningful CNS penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Sotorasib, a dissimilar acrylamide-containing molecule, was strongly restricted by ABCB1 efflux in mice, indicating that acrylamide alone does not guarantee brain penetration.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Evobrutinib is a CNS-penetrant BTK inhibitor; direct NHP CSF detection and supportive brain-exposure data from close analogues outweigh the single efflux-limited negative control.",
  "evidence_gaps": [
    "No quantitative Kp,uu or human CSF/plasma ratio for evobrutinib itself in the retrieved records; C12 is qualitative CSF detection in NHPs.",
    "Efflux liability not directly assessed for evobrutinib in the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

